{
  "avaliacoes": [
    {
      "id": "E9547e47dabdaf296",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Óleos pesados e extrapesados são descritos como mais propensos à formação de emulsões estáveis devido à presença de compostos orgânicos polares e surfactantes naturais do petróleo, como asfaltenos, resinas e ácidos naftênicos.",
          "trechos": [
            "E9547e47dabdaf296:0:698",
            "E9547e47dabdaf296:2092:2271"
          ],
          "condicoes": [
            "No contexto de produção, transporte e refino de óleos pesados ou extrapesados",
            "Quando a água presente encontra condições químicas ou físico-químicas favoráveis à emulsificação"
          ],
          "limites": [
            "O trecho não detalha como pH, salinidade, temperatura ou composição interfacial alteram a contribuição relativa de cada surfactante natural",
            "Não apresenta critério de seleção entre diferentes desemulsificantes"
          ]
        },
        {
          "proposicao": "As águas que compõem emulsões podem conter sais e óxidos metálicos que aumentam a viscosidade da emulsão, afetam bombeio e transferência e podem favorecer corrosão/oxidação e incrustações.",
          "trechos": [
            "E9547e47dabdaf296:698:1396"
          ],
          "condicoes": [
            "Quando a água emulsionada contém sais como cloretos de sódio, cálcio e magnésio e óxidos metálicos"
          ],
          "limites": [
            "O trecho não separa quantitativamente o efeito de cada sal ou óxido sobre viscosidade, corrosão e incrustação",
            "Os limites numéricos de teor final de água e sal aparecem apagados e não podem ser reconstruídos"
          ]
        },
        {
          "proposicao": "O processamento primário é descrito como remoção de água, sais e eventualmente gases por uso de produtos químicos desemulsificantes e vasos tratadores, com destaque para desidratadores eletrostáticos nos quais a água emulsionada coalesce e é removida por decantação.",
          "trechos": [
            "E9547e47dabdaf296:1396:2092"
          ],
          "condicoes": [
            "Antes do transporte do petróleo para a refinaria",
            "No contexto de desidratação e dessalgação do petróleo"
          ],
          "limites": [
            "A afirmação de que a eletrocoalescência é o melhor método aparece como avaliação do texto, não como regra universal",
            "Não há dosagens de químicos, parâmetros de campo elétrico, temperatura ou tempo de residência"
          ]
        }
      ]
    },
    {
      "id": "E6d67b77ff60cd743",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A água produzida pode conter químicos adicionados ao processo, metais pesados e, por vezes, radioatividade, o que amplia o escopo de compatibilidade e controle além do simples teor de óleo.",
          "trechos": [
            "E6d67b77ff60cd743:0:695",
            "E6d67b77ff60cd743:1394:2090"
          ],
          "condicoes": [
            "No contexto de composição da água produzida ao longo dos processos de produção"
          ],
          "limites": [
            "O trecho não relaciona cada contaminante a um método específico de remoção ou a uma incompatibilidade química específica",
            "As concentrações numéricas citadas para alguns metais estão parcialmente apagadas"
          ]
        },
        {
          "proposicao": "A distinção entre água livre e água emulsionada na água produzida é associada ao diâmetro de gota e ao histórico de cisalhamento, sendo a água livre separável por decantação e a água emulsionada relativamente estável.",
          "trechos": [
            "E6d67b77ff60cd743:0:695"
          ],
          "condicoes": [
            "Água livre quando o diâmetro da gota favorece coalescência",
            "Água emulsionada quando há mistura íntima decorrente de cisalhamento em bombas, válvulas e equipamentos"
          ],
          "limites": [
            "O trecho não fornece critério quantitativo de tamanho de gota",
            "Não informa quais condições de processo podem converter um regime no outro"
          ]
        },
        {
          "proposicao": "Na água produzida, cloretos são associados principalmente à corrosão, enquanto sulfatos e carbonatos são associados à incrustação; a composição depende fortemente do campo e da história geológica da formação.",
          "trechos": [
            "E6d67b77ff60cd743:695:1394"
          ],
          "condicoes": [
            "Quando a água produzida contém sais solúveis como cloretos, sulfatos e carbonatos de sódio, potássio, cálcio e magnésio"
          ],
          "limites": [
            "A associação é explicativa e não exclui outros mecanismos de corrosão ou incrustação",
            "Não há teste de compatibilidade, dosagem química ou critério operacional de mitigação no trecho"
          ]
        }
      ]
    },
    {
      "id": "E8f5684c21de5e126",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A falta de compatibilidade química entre águas de diferentes origens pode gerar precipitados, de modo que testes são indicados para determinar essa compatibilidade.",
          "trechos": [
            "E8f5684c21de5e126:0:690",
            "E8f5684c21de5e126:690:1390"
          ],
          "condicoes": [
            "Quando se misturam águas da formação com água de injeção ou outras águas de composição variável"
          ],
          "limites": [
            "O trecho indica a necessidade de testes, mas não define método, critério de aceitação ou protocolo operacional",
            "Não estabelece que toda mistura de águas seja incompatível"
          ]
        },
        {
          "proposicao": "A presença de sulfato e carbonato junto com cálcio, bário e estrôncio é apresentada como condição para formação de incrustações, inclusive com possibilidade de incrustações radioativas envolvendo Ra226.",
          "trechos": [
            "E8f5684c21de5e126:690:1390"
          ],
          "condicoes": [
            "Na presença simultânea de SO42- e CO32- com Ca2+, Ba2+ e Sr2+",
            "No contexto de composição iônica da água produzida"
          ],
          "limites": [
            "O trecho não quantifica supersaturação, cinética de precipitação ou efeito de temperatura e pressão",
            "A menção a radionuclídeos descreve possibilidade, não frequência obrigatória"
          ]
        },
        {
          "proposicao": "Aditivos como desemulsificantes, coagulantes, floculantes, biocidas, inibidores de corrosão, antiespumantes, inibidores de incrustação e de hidratos podem ser usados conforme implicações específicas de cada poço.",
          "trechos": [
            "E8f5684c21de5e126:1390:2090",
            "E8f5684c21de5e126:2090:2401"
          ],
          "condicoes": [
            "Quando características específicas do poço exigem melhoria de processo ou mitigação de problemas operacionais"
          ],
          "limites": [
            "O trecho é uma enumeração de classes químicas e não traz dosagem, compatibilidade entre produtos nem critérios de seleção",
            "Não vincula cada aditivo a um ponto exato da planta"
          ]
        }
      ]
    },
    {
      "id": "E0ad8bc874313c73e",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A qualidade da água produzida pode variar amplamente entre poços e ao longo da vida do campo, o que é apresentado como complicador para processos futuros de tratamento.",
          "trechos": [
            "E0ad8bc874313c73e:0:698"
          ],
          "condicoes": [
            "Quando uma mesma unidade recebe efluentes de múltiplos poços e de origens onshore e offshore",
            "Ao longo da vida útil do campo produtor"
          ],
          "limites": [
            "O trecho descreve um exemplo operacional e não generaliza quantitativamente a variação para qualquer instalação",
            "Não informa estratégia de controle adaptativo ou ajuste de dosagem química"
          ]
        },
        {
          "proposicao": "O óleo na água produzida é classificado como livre, disperso, emulsionado ou dissolvido, e a facilidade de remoção diminui do óleo livre para o dissolvido, com a remoção do dissolvido sendo descrita como extremamente difícil e dependente de processos químicos e/ou biológicos.",
          "trechos": [
            "E0ad8bc874313c73e:698:1396"
          ],
          "condicoes": [
            "No contexto de tratamento de água produzida",
            "Dependendo do modo físico em que o óleo se encontra na água"
          ],
          "limites": [
            "Os intervalos numéricos de diâmetro de gota estão apagados e não podem ser reconstruídos",
            "O trecho não relaciona diretamente cada classe de óleo com tecnologias específicas como hidrociclones ou flotação"
          ]
        },
        {
          "proposicao": "A água produzida pode conter sais minerais dissolvidos, sólidos de corrosão, graxas, asfaltenos, gases dissolvidos e químicos adicionados para prevenir ou tratar problemas operacionais, como biocidas, anti-incrustantes, antiespumantes e inibidores de corrosão.",
          "trechos": [
            "E0ad8bc874313c73e:1396:2093"
          ],
          "condicoes": [
            "Na composição geral da água produzida proveniente de campos de óleo"
          ],
          "limites": [
            "O trecho não diferencia contribuição relativa de cada classe de contaminante para emulsão, espuma, corrosão ou incrustação",
            "Não apresenta compatibilidade entre os aditivos listados"
          ]
        }
      ]
    },
    {
      "id": "E57a0e23c7c10fd27",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Sob condições específicas, asfaltenos podem precipitar e obstruir poros da rocha, equipamentos e oleodutos, com redução de produção, restrição ao escoamento e perda de pressão.",
          "trechos": [
            "E57a0e23c7c10fd27:0:696"
          ],
          "condicoes": [
            "Sob condições específicas não detalhadas no trecho",
            "Ao longo do reservatório, coluna de produção, equipamentos e oleodutos"
          ],
          "limites": [
            "O trecho não explicita quais condições específicas desencadeiam a precipitação",
            "Não trata de dosagem ou seleção de inibidores/dispersantes de asfaltenos"
          ]
        },
        {
          "proposicao": "Na interface óleo-água, asfaltenos estabilizam emulsões água-em-óleo ao formar uma barreira mecânica à aglutinação das gotas durante colisões, o que fundamenta a necessidade de desemulsificação do óleo.",
          "trechos": [
            "E57a0e23c7c10fd27:696:1390"
          ],
          "condicoes": [
            "Quando asfaltenos se adsorvem e agregam na interface óleo-água"
          ],
          "limites": [
            "O trecho não informa como essa barreira responde a temperatura, salinidade, pH ou tipo de desemulsificante",
            "Não compara a contribuição dos asfaltenos com a de resinas ou outros surfactantes naturais"
          ]
        },
        {
          "proposicao": "Na interface gás-óleo, asfaltenos são associados à formação de espumas muito estáveis de gás natural no petróleo, e o texto menciona a adição de antiespumantes silicones no processo de extração.",
          "trechos": [
            "E57a0e23c7c10fd27:1390:2090"
          ],
          "condicoes": [
            "Quando há formação de espuma estável na interface gás-óleo"
          ],
          "limites": [
            "A menção a silicones é descritiva e não define produto obrigatório, dosagem ou compatibilidade com outros químicos",
            "Não há critérios para prever quando a espuma exigirá antiespumante"
          ]
        }
      ]
    },
    {
      "id": "Ee707fa877ddac2d6",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A água de produção é apresentada como fonte de problemas operacionais recorrentes, incluindo emulsões, corrosão, incrustação, crescimento microbiano, partículas em suspensão, espumas e sujeiras de equipamentos, o que motiva o uso de diferentes classes de produtos químicos.",
          "trechos": [
            "Ee707fa877ddac2d6:0:699",
            "Ee707fa877ddac2d6:699:1394"
          ],
          "condicoes": [
            "No contexto de operações de campo com água de produção"
          ],
          "limites": [
            "O trecho não define prioridade de tratamento, compatibilidade entre produtos ou critérios de aplicação",
            "A enumeração de problemas não estabelece nexo causal exclusivo entre cada problema e cada químico"
          ]
        },
        {
          "proposicao": "Constituintes como sais dissolvidos, oxigênio, dióxido de carbono e sulfeto de hidrogênio são apontados como agentes de corrosão, e os inibidores de corrosão são descritos como substâncias que se adsorvem na superfície metálica e limitam a difusão do agente corrosivo.",
          "trechos": [
            "Ee707fa877ddac2d6:699:1394"
          ],
          "condicoes": [
            "Quando esses constituintes estão presentes na água de produção em contato com equipamentos metálicos"
          ],
          "limites": [
            "O trecho descreve mecanismo geral e exemplos de sais, mas não fornece critério de seleção por material, pH, temperatura ou regime de escoamento",
            "Os exemplos citados não devem ser convertidos em requisito normativo ou receita universal"
          ]
        },
        {
          "proposicao": "A incrustação é explicada como precipitação de sais inorgânicos quando a água produzida sofre redução de temperatura e pressão em relação às condições do reservatório, alterando o equilíbrio químico termodinâmico.",
          "trechos": [
            "Ee707fa877ddac2d6:1394:2094",
            "Ee707fa877ddac2d6:2094:2388"
          ],
          "condicoes": [
            "Durante a produção, quando temperatura e pressão da água são reduzidas em relação às condições do reservatório"
          ],
          "limites": [
            "O trecho não indica quais sais precipitam em cada cenário nem como prever saturação",
            "Não traz desempenho, dosagem ou janela operacional de inibidores de incrustação"
          ]
        }
      ]
    }
  ],
  "concluir": false,
